function S(t){const n=Math.max(0,Math.min(100,Number(t)||0));return Math.round(5e7+25e6*(n/100))}function V(t){const n=Math.max(0,Math.min(100,Number(t)||50));return Math.round(70+n*.3)}const h=175e6,b=225e6,f=225e6,N=375e6;function c(t){const n=Math.max(0,Math.min(100,Number(t)||0));return Math.max(.5,Math.min(2,n/50))}function E(t){return Math.round(h*c(t))}function B(t){return Math.round(b*c(t))}function C(t){return Math.round(f*c(t))}function x(t){return Math.round(N*c(t))}function p(t){let n=0;for(const a of t||[])n+=Math.round(Number(a.purchase_price||0)*(Number(a.condition||0)/100));return n}function d(t,n){let a=0;const o=Number(n||0);for(const u of t||[]){if(u.status==="for_sale")continue;const e=Math.max(0,Math.floor((o-Number(u.built_at_tick||0))/12)),r=Math.max(.2,1-.05*e),i=Number(u.condition||0)/100;a+=Math.round(Number(u.purchase_price||0)*r*i)}return a}function A({cash:t,loans:n,properties:a,propertyValue:o,vessels:u,equipmentValue:e,financeReceivables:r,currentTick:i}){const s=o!=null?Number(o):p(a),l=e!=null?Number(e):d(u,i),m=Math.max(0,Number(r||0)),_=Number(n||0),M=Number(t||0)+s+l+m-_;return{cash:Number(t||0),propertyValue:s,equipmentValue:l,financeReceivables:m,liabilities:_,valuationBasis:M,valuation:Math.round(M*1.3)}}function y({cash:t,loans:n,properties:a,propertyValue:o,vessels:u,equipmentValue:e,financeReceivables:r,currentTick:i}){return A({cash:t,loans:n,properties:a,propertyValue:o,vessels:u,equipmentValue:e,financeReceivables:r,currentTick:i}).valuation}export{A as a,d as b,y as c,V as d,c as e,C as f,B as g,x as h,E as l,S as n};
